from langchain_core.runnables import RunnableLambda, RunnableBranch

def route(info):
    if info['score'] > 90:
        return RunnableLambda(lambda x: 'Excellent')
    return RunnableLambda(lambda x: 'Good')

# Using RunnableLambda for custom routing
chain = RunnableLambda(lambda x: route(x)).invoke({'score': 95})
print(chain.invoke({}))
